    depthWrite: false,
    depthTest: false
  });
  const mesh = new THREE.Mesh(geom, mat);
  mesh.renderOrder = 8;
  scene.add(mesh);
  return mesh;
}
function replaceTubeGeometry(mesh, points, radius, segments = 160) {
  const old = mesh.geometry;
  mesh.geometry = new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points), segments, radius, 10, false);
  old.dispose();
}

const rimPts = [];
for (let j = 0; j <= 180; j++) {
