figKey.position.set(-3.5, 5.5, 4.5);
scene.add(figKey);
const figFill = new THREE.DirectionalLight(0xffd9b0, 0.35);
figFill.position.set(4, 2, -3);
scene.add(figFill);

const P0 = new THREE.Vector3(0, 1.15, 0);
const surfA = 3.2;
const surfB = 2.4;

function surfaceHeight(x, y) {
  return 1.15 + 0.12 * x - 0.08 * y - 0.18 * x * x - 0.11 * y * y + 0.04 * x * y;
}
function planeHeight(x, y) {
  return 1.15 + 0.12 * x - 0.08 * y;
}
function worldSurface(x, y, lift = 0) {
  return new THREE.Vector3(x, surfaceHeight(x, y) + lift, y);
}
function worldPlane(x, y) {
  return new THREE.Vector3(x, planeHeight(x, y), y);
}

function makeOvalSurfaceGeometry(rMax = 1, rings = 46, segs = 112, lift = 0, withColors = true) {
  const positions = [];
  const colors = [];
  const indices = [];
  const centerColor = new THREE.Color(0xf9ddb0);
  const midColor = new THREE.Color(0xf6a14a);
  const rimColor = new THREE.Color(0xff7a25);

  positions.push(0, surfaceHeight(0, 0) + lift, 0);
  if (withColors) colors.push(centerColor.r, centerColor.g, centerColor.b);

  for (let i = 1; i <= rings; i++) {
    const r = (i / rings) * rMax;
    for (let j = 0; j < segs; j++) {
      const th = (j / segs) * Math.PI * 2;
      const x = surfA * r * Math.cos(th);
      const y = surfB * r * Math.sin(th);
      const p = worldSurface(x, y, lift);
      positions.push(p.x, p.y, p.z);

      if (withColors) {
        const c = new THREE.Color();
        if (r < 0.58) c.lerpColors(centerColor, midColor, r / 0.58);
        else c.lerpColors(midColor, rimColor, (r - 0.58) / 0.42);
        const warm = THREE.MathUtils.clamp((p.y + 0.55) / 1.8, 0, 1);
        c.lerp(new THREE.Color(0xffffff), 0.10 * warm);
        colors.push(c.r, c.g, c.b);
      }
    }
  }

  const idx = (i, j) => i === 0 ? 0 : 1 + (i - 1) * segs + ((j % segs + segs) % segs);

  for (let j = 0; j < segs; j++) {
    indices.push(idx(0, 0), idx(1, j), idx(1, j + 1));
  }
  for (let i = 1; i < rings; i++) {
    for (let j = 0; j < segs; j++) {
      indices.push(idx(i, j), idx(i + 1, j), idx(i, j + 1));
      indices.push(idx(i, j + 1), idx(i + 1, j), idx(i + 1, j + 1));
    }
  }

  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  if (withColors) geom.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  geom.setIndex(indices);
  geom.computeVertexNormals();
  geom.computeBoundingSphere();
  return geom;
}

const surfaceMat = new THREE.MeshPhongMaterial({
  color: 0xffffff,
  vertexColors: true,
  side: THREE.DoubleSide,
  transparent: true,
  opacity: 0.72,
  shininess: 38,
  depthWrite: false
});
const surfaceMesh = new THREE.Mesh(makeOvalSurfaceGeometry(1, 48, 128, 0, true), surfaceMat);
surfaceMesh.renderOrder = 0;
scene.add(surfaceMesh);

const overlapMat = new THREE.MeshBasicMaterial({
  color: 0xcbd8b6,
  side: THREE.DoubleSide,
  transparent: true,
  opacity: 0.31,
  depthWrite: false
});
const overlapMesh = new THREE.Mesh(makeOvalSurfaceGeometry(0.73, 28, 96, 0.012, false), overlapMat);
overlapMesh.renderOrder = 2;
scene.add(overlapMesh);

function makeTube(points, radius, color, opacity = 1, tubularSegments = 160) {
  const curve = new THREE.CatmullRomCurve3(points);
  const geom = new THREE.TubeGeometry(curve, tubularSegments, radius, 10, false);
  const mat = new THREE.MeshBasicMaterial({
    color,
    transparent: true,
    opacity,
    depthWrite: false,
    depthTest: false
  });
  const mesh = new THREE.Mesh(geom, mat);
  mesh.renderOrder = 8;
  scene.add(mesh);
  return mesh;
}
function replaceTubeGeometry(mesh, points, radius, segments = 160) {
  const old = mesh.geometry;
  mesh.geometry = new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points), segments, radius, 10, false);
  old.dispose();
}

const rimPts = [];
for (let j = 0; j <= 180; j++) {
  const th = (j / 180) * Math.PI * 2;
  rimPts.push(worldSurface(surfA * Math.cos(th), surfB * Math.sin(th), 0.018));
}
const rimMesh = makeTube(rimPts, 0.015, 0xff6f1a, 0.95, 210);
rimMesh.material.depthTest = true;
rimMesh.renderOrder = 3;

const longLen = 5.8;
const shortLen = 3.7;
const longDir = new THREE.Vector2(1, -0.2).normalize();
const shortDir = new THREE.Vector2(0.2, 1).normalize();
function planeDomainPoint(u, v) {
  const x = longDir.x * u + shortDir.x * v;
  const y = longDir.y * u + shortDir.y * v;
  return { x, y };
}
function planeWorldFromUV(u, v) {
  const dmn = planeDomainPoint(u, v);
  return worldPlane(dmn.x, dmn.y);
}
const uH = longLen / 2;
const vH = shortLen / 2;
const planeCorners = [
  planeWorldFromUV(-uH, -vH),
  planeWorldFromUV(uH, -vH),
  planeWorldFromUV(uH, vH),
  planeWorldFromUV(-uH, vH)
];
const planeGeom = new THREE.BufferGeometry().setFromPoints(planeCorners);
planeGeom.setIndex([0, 1, 2, 0, 2, 3]);
planeGeom.computeVertexNormals();
const planeMat = new THREE.MeshBasicMaterial({
  color: 0xdff3fb,
  transparent: true,
  opacity: 0.48,
  side: THREE.DoubleSide,
  depthWrite: false,
  depthTest: false
});
const planeMesh = new THREE.Mesh(planeGeom, planeMat);
planeMesh.renderOrder = 4;
scene.add(planeMesh);

const edgeMat = new THREE.MeshBasicMaterial({
  color: 0xeaf9ff,
  transparent: true,
  opacity: 0.82,
  depthWrite: false,
  depthTest: false
});
const strongEdgeMat = new THREE.MeshBasicMaterial({
  color: 0xffffff,
  transparent: true,
  opacity: 0.92,
  depthWrite: false,
  depthTest: false
});
const planeEdges = [];
for (let i = 0; i < 4; i++) {
  const a = planeCorners[i];
  const b = planeCorners[(i + 1) % 4];
  const edge = new THREE.Mesh(
    new THREE.TubeGeometry(new THREE.CatmullRomCurve3([a, b]), 1, i === 0 ? 0.026 : 0.014, 8, false),
    i === 0 ? strongEdgeMat : edgeMat
  );
  edge.renderOrder = 5;
  scene.add(edge);
  planeEdges.push(edge);
}

const tealPts = [];
for (let i = 0; i <= 170; i++) {
  const x = -2.5 + (5.1 * i) / 170;
  const y = 0.22 * x - 0.045 * x * x;
  tealPts.push(worldSurface(x, y, 0.032));
}
const redPts = [];
for (let i = 0; i <= 150; i++) {
  const t = -1.9 + (3.45 * i) / 150;
  const x = 0.22 * t;
  const y = -t;
  redPts.push(worldSurface(x, y, 0.04));
}

function tangentPointsFromMathDirection(dx, dy, dz, len) {
  const dir = new THREE.Vector3(dx, dz, dy).normalize();
  return [
    P0.clone().addScaledVector(dir, -len / 2),
    P0.clone().addScaledVector(dir, len / 2)
  ];
}
const tealTanPts = tangentPointsFromMathDirection(1, 0.22, 0.12 - 0.08 * 0.22, 4.6);
const redTanPts = tangentPointsFromMathDirection(0.22, -1, 0.12 * 0.22 + 0.08, 3.7);

const tealCurve = makeTube(tealPts, 0.021, 0x008b8b, 0.97, 180);
const tealTangent = makeTube(tealTanPts, 0.018, 0x008b8b, 0.97, 2);
const redCurve = makeTube(redPts, 0.021, 0xd8243c, 0.98, 160);
const redTangent = makeTube(redTanPts, 0.018, 0xd8243c, 0.98, 2);

const p0Mesh = new THREE.Mesh(
  new THREE.SphereGeometry(0.055, 24, 16),
  new THREE.MeshBasicMaterial({ color: 0x000000, depthTest: false, depthWrite: false })
);
p0Mesh.position.copy(P0);
p0Mesh.renderOrder = 20;
scene.add(p0Mesh);

registerInteractive(tealCurve, {
  title: 'Teal curve through P₀',
  tooltip: 'Click to highlight the teal curve and tangent line',
  body: 'This teal path lies on the curved surface and passes through P₀. Its straight tangent line at P₀ lies in the blue tangent plane.',
  onClick: () => setSelectedCurve('teal')
});
registerInteractive(tealTangent, {
  title: 'Teal tangent line',
  tooltip: 'The teal tangent line lies in the tangent plane',
  body: 'The teal straight line is tangent to the teal surface curve at P₀ and remains inside the tangent plane.',
  onClick: () => setSelectedCurve('teal')
});
registerInteractive(redCurve, {
  title: 'Red curve through P₀',
  tooltip: 'Click to highlight the red curve and tangent line',
  body: 'This red path is a different curve on the same surface through P₀. Its tangent direction is different, but its tangent line is still contained in the same plane.',
  onClick: () => setSelectedCurve('red')
});
registerInteractive(redTangent, {
  title: 'Red tangent line',
  tooltip: 'The red tangent line also lies in the tangent plane',
  body: 'The red tangent line and the teal tangent line are two examples of tangent directions contained by the tangent plane at P₀.',
  onClick: () => setSelectedCurve('red')
});
registerInteractive(p0Mesh, {
  title: 'Point P₀',
  tooltip: 'P₀ is the point of tangency',
  body: 'At P₀ the blue plane touches the surface. Curves on the surface through P₀ have tangent lines in this plane.'
});

setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  rollDeg: 0,
  heightFraction: 0.72
});

addLabel('Tangent plane at<br><i>P</i><sub>0</sub>{x<sub>0</sub>, y<sub>0</sub>, z<sub>0</sub>}', new THREE.Vector3(-0.45, 1.86, -0.18), {
  fontSize: '18px',
  color: '#111',
  offset: [-4, -6]
});
addLabel('Curve C<br>passes through<br><i>P</i><sub>0</sub>{x<sub>0</sub>, y<sub>0</sub>, z<sub>0</sub>}', new THREE.Vector3(-2.35, 0.15, -1.28), {
  fontSize: '18px',
  color: '#111',
  offset: [-10, 4]
});
addLabel('S', worldSurface(2.05, -1.65, 0.08), {
  fontSize: '19px',
  color: '#111',
  offset: [4, 8]
});

let planeTargetOpacity = 0.48;
let planeCurrentOpacity = 0.48;
let planeModeState = 'With tangent plane';
let selectedCurve = 'both';

const planeModeBtn = document.getElementById('planeMode');
const selectCurveBtn = document.getElementById('selectCurve');
const curveBothBtn = document.getElementById('curveBoth');
const curveTealBtn = document.getElementById('curveTeal');
const curveRedBtn = document.getElementById('curveRed');
const narrationEl = document.getElementById('stepNarration');

function setPlaneMode(mode) {
  planeModeState = mode === 'Surface only' ? 'Surface only' : 'With tangent plane';
  planeTargetOpacity = planeModeState === 'Surface only' ? 0 : 0.48;
  planeModeBtn.textContent = planeModeState;
  planeModeBtn.classList.toggle('active', planeModeState === 'With tangent plane');
}
function setSelectedCurve(which) {
  selectedCurve = which || 'both';
  curveBothBtn.classList.toggle('active', selectedCurve === 'both');
  curveTealBtn.classList.toggle('active', selectedCurve === 'teal');
  curveRedBtn.classList.toggle('active', selectedCurve === 'red');
  selectCurveBtn.textContent = selectedCurve === 'both'
    ? 'Compare curves: both'
    : selectedCurve === 'teal'
      ? 'Compare curves: teal'
      : 'Compare curves: red';
  applyCurveStyles(true);
}
function curveOpacity(which) {
  if (selectedCurve === 'both') return 0.98;
  return selectedCurve === which ? 1 : 0.25;
}
function curveRadius(which, tangent = false) {
  if (selectedCurve === 'both') return tangent ? 0.018 : 0.021;
  if (selectedCurve === which) return tangent ? 0.026 : 0.031;
  return tangent ? 0.012 : 0.014;
}
function applyCurveStyles(rebuild = false) {
  tealCurve.material.opacity = curveOpacity('teal');
  redCurve.material.opacity = curveOpacity('red');
  tealTangent.material.opacity = planeCurrentOpacity > 0.01 ? curveOpacity('teal') : 0;
  redTangent.material.opacity = planeCurrentOpacity > 0.01 ? curveOpacity('red') : 0;

  if (rebuild) {
    replaceTubeGeometry(tealCurve, tealPts, curveRadius('teal', false), 180);
    replaceTubeGeometry(redCurve, redPts, curveRadius('red', false), 160);
    replaceTubeGeometry(tealTangent, tealTanPts, curveRadius('teal', true), 2);
    replaceTubeGeometry(redTangent, redTanPts, curveRadius('red', true), 2);
  }
}

planeModeBtn.addEventListener('click', () => {
  setPlaneMode(planeModeState === 'With tangent plane' ? 'Surface only' : 'With tangent plane');
});
selectCurveBtn.addEventListener('click', () => {
  setSelectedCurve(selectedCurve === 'both' ? 'teal' : selectedCurve === 'teal' ? 'red' : 'both');
});
curveBothBtn.addEventListener('click', () => setSelectedCurve('both'));
curveTealBtn.addEventListener('click', () => setSelectedCurve('teal'));
curveRedBtn.addEventListener('click', () => setSelectedCurve('red'));

const demoSteps = [
  {
    title: 'Surface paths through P0',
    narration: 'Begin with the orange surface and the two colored curves passing through the same point P0. Each curve represents a possible path on the surface through that point.',
    state: { planeMode: 'Surface only', selected: 'both' }
  },
  {
    title: 'Reveal the tangent plane',
    narration: 'Fade in the translucent blue plane. The straight tangent lines for both colored curves lie inside this same flat sheet, showing why it is called the tangent plane at P0.',
    state: { planeMode: 'With tangent plane', selected: 'both' }
  },
  {
    title: 'Compare the two directions',
    narration: 'Click the teal or red curve to brighten that curve and its tangent line. The other curve dims, making the shared plane easier to see.',
    state: { planeMode: 'With tangent plane', selected: 'teal' }
  }
];

window.goToStep = function goToStep(i) {
  const step = demoSteps[Math.max(0, Math.min(demoSteps.length - 1, i | 0))];
  setPlaneMode(step.state.planeMode);
  setSelectedCurve(step.state.selected);
  narrationEl.innerHTML = `<b>${step.title}</b><br>${step.narration}`;
};

document.getElementById('step0').addEventListener('click', () => window.goToStep(0));
document.getElementById('step1').addEventListener('click', () => window.goToStep(1));
document.getElementById('step2').addEventListener('click', () => window.goToStep(2));

function fadePlaneLoop() {
  requestAnimationFrame(fadePlaneLoop);
  planeCurrentOpacity += (planeTargetOpacity - planeCurrentOpacity) * 0.09;
  if (Math.abs(planeCurrentOpacity - planeTargetOpacity) < 0.002) planeCurrentOpacity = planeTargetOpacity;

  planeMat.opacity = planeCurrentOpacity;
  edgeMat.opacity = planeCurrentOpacity * 1.7;
  strongEdgeMat.opacity = planeCurrentOpacity * 1.9;
  overlapMat.opacity = planeCurrentOpacity * 0.66;

  const visible = planeCurrentOpacity > 0.01;
  planeMesh.visible = visible;
  overlapMesh.visible = visible;
  for (const e of planeEdges) e.visible = visible;

  tealTangent.material.opacity = visible ? curveOpacity('teal') * (planeCurrentOpacity / 0.48) : 0;
  redTangent.material.opacity = visible ? curveOpacity('red') * (planeCurrentOpacity / 0.48) : 0;
}
fadePlaneLoop();

setPlaneMode('With tangent plane');
setSelectedCurve('both');
window.goToStep(1);
// @FIGURE_CODE_END

