const P0 = new THREE.Vector3(0, 1.15, 0);
const surfA = 3.2;
const surfB = 2.4;

function surfaceHeight(x, z) {
  return 1.15 + 0.12 * x - 0.08 * z - 0.18 * x * x - 0.11 * z * z + 0.04 * x * z;
}
function planeHeight(x, z) {
  return 1.15 + 0.12 * x - 0.08 * z;
}
function worldSurface(x, z, lift = 0) {
  return new THREE.Vector3(x, surfaceHeight(x, z) + lift, z);
}
function worldPlane(x, z) {
  return new THREE.Vector3(x, planeHeight(x, z), z);
}
function boundaryScale(th) {
  const s = 1
    + 0.20 * Math.sin(th - 0.72)
    - 0.13 * Math.cos(2 * th + 0.35)
    + 0.075 * Math.sin(3 * th + 1.55);
  return THREE.MathUtils.clamp(s, 0.72, 1.22);
}
function boundaryPoint(th, rMax = 1) {
  const b = boundaryScale(th);
  const zSkew = 1 + 0.08 * Math.cos(th - 1.1);
  const x = surfA * rMax * b * Math.cos(th);
  const z = surfB * rMax * b * zSkew * Math.sin(th);
  return { x, z };
}

function makeSweptSurfaceGeometry(rMax = 1, rings = 52, segs = 132, lift = 0, withColors = true) {
  const positions = [];
  const colors = [];
  const indices = [];
  const centerColor = new THREE.Color(0xf9ddb0);
  const midColor = new THREE.Color(0xf6a14a);
  const rimColor = new THREE.Color(0xff7a25);

  positions.push(0, surfaceHeight(0, 0) + lift, 0);
  if (withColors) colors.push(centerColor.r, centerColor.g, centerColor.b);

  for (let i = 1; i <= rings; i++) {
    const r = i / rings;
    for (let j = 0; j < segs; j++) {
      const th = (j / segs) * Math.PI * 2;
      const bp = boundaryPoint(th, rMax * r);
      const p = worldSurface(bp.x, bp.z, lift);
      positions.push(p.x, p.y, p.z);

      if (withColors) {
        const c = new THREE.Color();
        if (r < 0.55) c.lerpColors(centerColor, midColor, r / 0.55);
        else c.lerpColors(midColor, rimColor, (r - 0.55) / 0.45);
        const highLight = THREE.MathUtils.clamp((p.y + 0.25) / 1.65, 0, 1);
        c.lerp(new THREE.Color(0xffffff), 0.10 * highLight);
        colors.push(c.r, c.g, c.b);
      }
    }
  }

  const idx = (i, j) => i === 0 ? 0 : 1 + (i - 1) * segs + ((j % segs + segs) % segs);

  for (let j = 0; j < segs; j++) {
    indices.push(idx(0, 0), idx(1, j), idx(1, j + 1));
  }
  for (let i = 1; i < rings; i++) {
    for (let j = 0; j < segs; j++) {
      indices.push(idx(i, j), idx(i + 1, j), idx(i, j + 1));
      indices.push(idx(i, j + 1), idx(i + 1, j), idx(i + 1, j + 1));
    }
  }

  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  if (withColors) geom.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  geom.setIndex(indices);
  geom.computeVertexNormals();
  geom.computeBoundingSphere();
  return geom;
}

