const longLen = 5.8;
const shortLen = 3.7;
const longDir = new THREE.Vector2(1, -0.24).normalize();
const shortDir = new THREE.Vector2(0.20, 1).normalize();
function planeDomainPoint(u, v) {
  const x = longDir.x * u + shortDir.x * v;
  const z = longDir.y * u + shortDir.y * v;
  return { x, z };
}
function planeWorldFromUV(u, v) {
  const dmn = planeDomainPoint(u, v);
  return worldPlane(dmn.x, dmn.z);
}
const uH = longLen / 2;
const vH = shortLen / 2;
const planeCorners = [
  planeWorldFromUV(-uH, -vH),
  planeWorldFromUV(uH, -vH),
  planeWorldFromUV(uH, vH),
  planeWorldFromUV(-uH, vH)
];
const planeGeom = new THREE.BufferGeometry().setFromPoints(planeCorners);
planeGeom.setIndex([0, 1, 2, 0, 2, 3]);
planeGeom.computeVertexNormals();
const planeMat = new THREE.MeshBasicMaterial({
